      function setQuestionError(fieldset, hasError) {
        const error = fieldset.querySelector(".error-message");
        const checkboxes = fieldset.querySelectorAll('input[type="checkbox"]');
        const describedBy = [fieldset.dataset.help, hasError ? error.id : ""].filter(Boolean).join(" ");

        error.hidden = !hasError;
        if (describedBy) {
          fieldset.setAttribute("aria-describedby", describedBy);
        } else {
          fieldset.removeAttribute("aria-describedby");
        }

        checkboxes.forEach((checkbox) => {
          if (hasError) {
            checkbox.setAttribute("aria-invalid", "true");
          } else {
            checkbox.removeAttribute("aria-invalid");
          }
        });
      }

      function isQuestionCorrect(fieldset) {
        const checkboxes = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));

        return checkboxes.every((checkbox) => checkbox.checked === (checkbox.dataset.correct === "true"));
      }

      questions.forEach((fieldset) => {
        fieldset.addEventListener("change", () => {
          if (fieldset.querySelector('input[type="checkbox"]:checked')) {
            setQuestionError(fieldset, false);
          }
        });
      });

      quiz.addEventListener("submit", (event) => {
        event.preventDefault();
        result.textContent = "";

        const firstIncompleteQuestion = questions.find((fieldset) => {
          const isIncomplete = !fieldset.querySelector('input[type="checkbox"]:checked');
          setQuestionError(fieldset, isIncomplete);
          return isIncomplete;
        });

        if (firstIncompleteQuestion) {
          firstIncompleteQuestion.querySelector('input[type="checkbox"]').focus();
          return;
        }

        const score = questions.filter(isQuestionCorrect).length;
        result.textContent = `You scored ${score} out of ${questions.length}.`;
      });
